<script setup lang="ts">import{computed,onMounted,ref,watch}from"vue";import{useRoute,useRouter}from"vue-router";import BaseEmptyState from"@/components/base/BaseEmptyState.vue";import BasePageHeader from"@/components/base/BasePageHeader.vue";import VodDeleteDialog from"@/components/vod/VodDeleteDialog.vue";import VodFilters from"@/components/vod/VodFilters.vue";import{availabilityRepository}from"@/domain/repositories";import{isExpired,money,qualityLabel,typeLabel}from"@/domain/vod/format";import{PocketBaseRepository}from"@/infrastructure/pocketbase/repository";import type{AvailabilityRecord,BaseRecord}from"@/types/records";type Country=BaseRecord&{nome?:string;codigo?:string};const route=useRoute(),router=useRouter(),repoCountries=new PocketBaseRepository<Country>('paises');const items=ref<AvailabilityRecord[]>([]),countries=ref<Country[]>([]),loading=ref(true),error=ref(""),search=ref(String(route.query.q||"")),country=ref(String(route.query.pais||"")),type=ref(String(route.query.tipo||"")),quality=ref(String(route.query.qualidade||"")),status=ref(String(route.query.estado||"active")),subscription=ref(String(route.query.subscricao||"")),deleteTarget=ref<AvailabilityRecord|null>(null),deleting=ref(false);const created=computed(()=>route.query.created==='1'),updated=computed(()=>route.query.updated==='1');const title=(i:AvailabilityRecord)=>i.expand?.titulo?.titulo||i.titulo;const countryName=(i:AvailabilityRecord)=>i.expand?.pais?.nome||i.expand?.pais?.codigo||'Global';const filtered=computed(()=>items.value.filter(i=>{const hay=`${title(i)} ${i.provider_nome}`.toLocaleLowerCase('pt-PT');if(search.value&&!hay.includes(search.value.toLocaleLowerCase('pt-PT')))return false;if(country.value&&i.pais!==country.value)return false;if(type.value&&i.tipo!==type.value)return false;if(quality.value&&i.qualidade!==quality.value)return false;if(status.value==='active'&&i.ativo===false)return false;if(status.value==='inactive'&&i.ativo!==false)return false;if(status.value==='expired'&&!isExpired(i.data_fim))return false;if(subscription.value==='yes'&&!i.incluido_subscricao)return false;if(subscription.value==='no'&&i.incluido_subscricao)return false;return true}));async function load(){loading.value=true;error.value="";try{const [page,cp]=await Promise.all([availabilityRepository.list({perPage:500,sort:'provider_nome',expand:'titulo,pais'}),repoCountries.list({perPage:500,sort:'nome'})]);items.value=page.items;countries.value=cp.items}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{loading.value=false}}async function toggle(item:AvailabilityRecord){await availabilityRepository.update(item.id,{ativo:item.ativo===false});await load()}async function remove(){if(!deleteTarget.value)return;deleting.value=true;try{await availabilityRepository.delete(deleteTarget.value.id);deleteTarget.value=null;await load()}finally{deleting.value=false}}function clear(){search.value=country.value=type.value=quality.value=subscription.value='';status.value='active'}watch([search,country,type,quality,status,subscription],()=>router.replace({name:'vod',query:{...(search.value?{q:search.value}:{}),...(country.value?{pais:country.value}:{}),...(type.value?{tipo:type.value}:{}),...(quality.value?{qualidade:quality.value}:{}),...(status.value!=='active'?{estado:status.value}:{}),...(subscription.value?{subscricao:subscription.value}:{})}}));onMounted(load);</script>
<template><div v-if="created" class="form-alert form-alert-success">Disponibilidade criada com sucesso.</div><div v-if="updated" class="form-alert form-alert-success">Disponibilidade atualizada com sucesso.</div><BasePageHeader eyebrow="Disponibilidade" title="VOD" :description="`${filtered.length} de ${items.length} ofertas`"><template #actions><RouterLink class="button button-primary" to="/vod/novo">＋ Adicionar disponibilidade</RouterLink></template></BasePageHeader><VodFilters v-model:search="search" v-model:country="country" v-model:type="type" v-model:quality="quality" v-model:status="status" v-model:subscription="subscription" :countries="countries" @clear="clear"/><section v-if="loading" class="page-loading"><span class="loader"/></section><BaseEmptyState v-else-if="error" icon="!" title="Não foi possível carregar o VOD" :description="error"><button class="button button-secondary" @click="load">Voltar a tentar</button></BaseEmptyState><div v-else-if="filtered.length" class="vod-grid"><article v-for="item in filtered" :key="item.id" class="panel vod-card" :class="{'is-inactive':item.ativo===false,'is-expired':isExpired(item.data_fim)}"><div class="vod-card-head"><div><span class="detail-badge detail-badge-primary">{{typeLabel(item.tipo)}}</span><span v-if="item.ativo===false" class="detail-badge detail-badge-danger">Inativa</span><span v-if="isExpired(item.data_fim)" class="detail-badge detail-badge-danger">Expirada</span><h2>{{title(item)}}</h2></div></div><dl class="vod-facts"><div><dt>Provider</dt><dd>{{item.provider_nome}}</dd></div><div><dt>País</dt><dd>{{countryName(item)}}</dd></div><div><dt>Qualidade</dt><dd>{{qualityLabel(item.qualidade)}}</dd></div><div><dt>Preço</dt><dd>{{money(item.preco,item.moeda)||(item.incluido_subscricao?'Incluído':'—')}}</dd></div></dl><div class="vod-actions"><RouterLink class="button button-secondary" :to="`/catalogo/${item.titulo}`">Título</RouterLink><a v-if="item.url" class="button button-primary" :href="item.url" target="_blank" rel="noopener noreferrer">Provider</a><RouterLink class="button button-secondary" :to="`/vod/${item.id}/editar`">Editar</RouterLink><button class="button button-secondary" @click="toggle(item)">{{item.ativo===false?'Ativar':'Desativar'}}</button><button class="button button-danger" @click="deleteTarget=item">Eliminar</button></div></article></div><BaseEmptyState v-else icon="▶" title="Nenhuma disponibilidade encontrada" description="Altera os filtros ou adiciona uma nova oferta."/><VodDeleteDialog :open="Boolean(deleteTarget)" :provider="deleteTarget?.provider_nome||''" :title="deleteTarget?title(deleteTarget):''" :deleting="deleting" @close="deleteTarget=null" @confirm="remove"/></template>
